    "input": all_grids.get("Demo pair 1 input"),
    "output": all_grids.get("Demo pair 1 output")
})
os.makedirs(os.path.dirname(task_file), exist_ok=True)
with open(task_file, 'w') as f:
    json.dump(demos, f)

print("Saved demos to:", task_file)
print("Demo input:")
