# Analyze where 6s change to 2s
input_grid = all_grids["Demo pair 1 input"]
output_grid = all_grids["Demo pair 1 output"]
h, w = len(input_grid), len(input_grid[0])

changed = []
for r in range(h):
    for c in range(w):
        if input_grid[r][c] == 6 and output_grid[r][c] != 6:
            changed.append((r, c))
        elif input_grid[r][c] != 6 and output_grid[r][c] == 6:
            changed.append((r, c))

print("\nChanged cells (6->2 or 2->6):")
for c in sorted(changed):
    print(c)

